#misterios{posición:relativa;desbordamiento:oculto}
    #misterios .wrap{posición:relativa;índice z:3}
    .myst-filterbar{display:flex;flex-wrap:wrap;gap:20px 28px;align-items:flex-end;margin-bottom:14px}
    .myst-filter-group{display:flex;flex-direction:column;gap:9px;min-width:0}
    .myst-filter-label{font-family:"Space Mono",ui-monospace,monospace;font-size:10px;letter-spacing:.24em;text-transform:uppercase;color:#d3a8c2}
    .myst-chip-row{display:flex;flex-wrap:wrap;gap:8px}
    .chip-místico{
      display:inline-flex;align-items:center;gap:8px;cursor:puntero;
      relleno: 9px 15px; radio de borde: 999px;
      familia de fuentes: "Espacio Mono", ui-monospace, monospace; tamaño de fuente: 11px;
      espacio entre letras: .14em; transformación de texto: mayúscula; color:#f4e3d7;
      fondo:rgba(20,7,44,.72);borde:1px solid rgba(255,45,124,.3);
      transición:transformar .15s facilidad,box-shadow .2s facilidad,border-color .2s facilidad;
    }
    .myst-chip:hover{transform:translateY(-1px);border-color:rgba(255,45,124,.65);box-shadow:0 0 20px rgba(255,45,124,.25)}
    .myst-chip.activo{
      fondo:var(--vi-grad-sunset,linear-gradient(90deg,#ff2d7c,#ff8a3d 52%,#ffd166));
      color:var(--vi-ink,#33051c);color del borde:transparente;peso de fuente:700;
      sombra de cuadro: 0 8px 22px -8px rgba (255,45,124, .65);
    }
    .myst-chip .myst-dot{ancho:8px;alto:8px;border-radius:99px;flex:0 0 auto}
    .myst-chip.active .myst-dot{esquema:1px solid rgba(51,5,28,.4)}
    .myst-dot--resolved{fondo:linear-gradient(135deg,var(--vi-gold,#ffd166),#7ee08c)}
    .myst-dot--open{fondo:var(--vi-pink,#ff2d7c);box-shadow:0 0 10px rgba(255,45,124,.8)}
    .myst-dot--lenda{fondo:var(--vi-purple,#7b2ff7);box-shadow:0 0 10px rgba(123,47,247,.8)}
    .myst-dot--todos{fondo:#f4e3d7}
    .myst-chip pequeño{
      tamaño de fuente: 10px; relleno: 2px 7px; radio de borde: 99px; espacio entre letras: .08em;
      fondo:rgba(11,13,42,.55);color:heredar;borde:1px solid rgba(255,255,255,.18);
    }
    .myst-chip.active pequeño{fondo:rgba(51,5,28,.22);color del borde:rgba(51,5,28,.3)}
    .myst-seleccionar{
      apariencia: ninguna; -webkit-apariencia: ninguna; cursor: puntero; ancho mínimo: 220 px;
      relleno: 10 px 38 px 10 px 14 px; radio de borde: 10 px;
      font-family:"Space Mono",ui-monospace,monospace;tamaño de fuente:12px;espaciado entre letras:.06em;
      color:#fff5ec;fondo:rgba(20,7,44,.72);borde:1px solid rgba(255,45,124,.3);
      imagen de fondo:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='12' height='8' viewBox='0 0 12 8'><path d='M1 1l5 5 5-5' fill='none' Stroke='%23ff2d7c' trazo-width='2' trazo-linecap='redondo'/></svg>");
      repetición de fondo: sin repetición; posición de fondo: centro derecho de 14 píxeles;
    }
    .myst-select:focus{outline:none;border-color:rgba(255,45,124,.7);box-shadow:0 0 18px rgba(255,45,124,.3)}
    .opción myst-select{fondo:#0b0d2a;color:#fff5ec}
    .myst-status-desc{
      margen:0 0 18px;ancho máximo:760px;color:#d9c3d2;tamaño de fuente:14px;alto de línea:1.6;
      borde izquierdo: 3px sólido rgba (255,45,124, .55); relleno izquierdo: 14px;
    }
    .myst-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(330px,1fr));gap:18px;align-items:start}
    .myst-card{display:flex;flex-direction:column;gap:0;padding:22px 22px 18px}
    .myst-card-top{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:14px}
    .myst-file-no{font-family:"Space Mono",ui-monospace,monospace;font-size:10px;letter-spacing:.22em;color:#b98ca9;text-transform:uppercase}
    .myst-stamp{transformar:rotar(-2deg);tamaño de fuente:10px;espaciado entre letras:.2em;padding:6px 13px}
    .myst-stamp--resuelto{
      fondo:gradiente lineal(90deg,var(--vi-gold,#ffd166),#7ee08c);
      color:var(--vi-ink,#33051c);box-shadow:0 8px 22px -8px rgba(255,209,102,.7),0 0 20px rgba(126,224,140,.25);
    }
    .myst-stamp--open{color:var(--vi-pink,#ff2d7c);box-shadow:0 0 22px rgba(255,45,124,.4)}
    .myst-stamp--leyenda{
      color:#cfa9ff;box-shadow:0 0 22px rgba(123,47,247,.45);
      antecedentes:
        gradiente lineal (rgba (26,9,54, .9), rgba (26,9,54, .9)) cuadro de relleno,
        gradiente lineal (90 grados, var (--vi-purple, # 7b2ff7), var (--vi-pink-2, # f152ff)) cuadro de borde;
    }
    .chip-juego-myst{
      display:inline-flex;align-items:center;gap:6px;margin-bottom:10px;
      familia de fuentes: "Espacio Mono", ui-monospace, monospace; tamaño de fuente: 10px;
      espacio entre letras: .18em; transformación de texto: mayúscula; color: var (--vi-gold, #ffd166);
    }
    .myst-game-chip::antes{contenido:"";ancho:14px;alto:1px;fondo:var(--vi-gold,#ffd166);opacidad:.7}
    .myst-card h3{margen:0 0 10px;tamaño de fuente:20px;altura de línea:1.25;color:#fff5ec}
    .myst-desc{margin:0;color:#d9c8d4;font-size:14px;line-height:1.62}
    .myst-toggle{margin-top:16px;align-self:flex-start}
    .myst-body{margin-top:16px;padding-top:16px;border-top:1px rgba discontinuo(255,45,124,.35)}
    .mística-etiqueta-evidencia{
      display:flex;align-items:center;gap:8px;margin:16px 0 4px;
      familia de fuentes: "Espacio Mono", ui-monospace, monospace; tamaño de fuente: 10px;
      espacio entre letras: .26em; transformación de texto: mayúscula; color: #ff9ec4;
    }
    .myst-evidence-label:primer-niño{margin-top:0}
    .myst-evidence-label::después{contenido:"";flex:1;altura:1px;fondo:rgba(255,45,124,.25)}
    .myst-list{estilo de lista:none;margin:8px 0 0;padding:0}
    .myst-list li{display:flex;gap:10px;align-items:baseline;margin-bottom:8px;color:#e6d6dd;font-size:13.5px;line-height:1.6}
    .myst-idx{
      flex:0 0 auto;font-family:"Space Mono",ui-monospace,monospace;font-size:10px;
      espacio entre letras:.08em;color:var(--vi-gold,#ffd166);opacidad:.85;min-width:30px;
    }
    .resolución misteriosa {
      margen superior: 18 px; relleno: 14 px 16 px; radio de borde: 10 px;
      borde: 1px rgba discontinuo (255,209,102,.6); fondo:rgba (255,209,102,.07);
    }
    .myst-resolución .myst-evidence-label{color:var(--vi-gold,#ffd166);margin-top:0}
    .myst-resolución .myst-evidence-label::después{fondo:rgba(255,209,102,.35)}
    .myst-resolución p{margin:8px 0 0;color:#ffe9bd;font-size:13.5px;line-height:1.62}
    .myst-dónde{
      display:flex;brecha:10px;align-items:baseline;margin-top:16px;
      familia de fuentes: "Espacio Mono", ui-monospace, monospace; tamaño de fuente: 12px;
      color:#cdb4c6;altura de línea:1,55;
    }
    .myst-where svg{flex:0 0 auto;ancho:14px;alto:14px;transformar:translateY(2px);color:var(--vi-pink,#ff2d7c)}
    .myst-vacío{
      relleno:34px 26px;text-align:center;color:#d3a8c2;
      font-family:"Space Mono",ui-monospace,monospace;tamaño de fuente:13px;espaciado entre letras:.08em;
    }
    @media (ancho máximo: 760 px){
      .myst-filterbar{flex-direction:column;align-items:stretch}
      .myst-select{ancho:100%}
      .myst-grid{columnas-de-plantilla-de-cuadrícula:1fr}
      .myst-card{relleno:18px 16px 16px}
    }
    @media (prefiere-movimiento-reducido:reducir){
      .myst-chip,.myst-chip:hover{transformar:ninguno;transición:ninguno}
    }
